export default function install(app){const search=document.getElementById('app-widget-place-search');const root=search?.shadowRoot;const autocomplete=root?.querySelector('calcite-autocomplete');const input=autocomplete?.shadowRoot?.querySelector('calcite-input');app.assert(root&&input?.shadowRoot,'Search input is not ready');const styles=[];app.onCleanup(()=>styles.forEach(s=>s.remove()));function add(target,css){const s=document.createElement('style');s.textContent=css;target.append(s);styles.push(s);}add(root,'calcite-dropdown.dropdown {display:none!important;}');add(input.shadowRoot,'.element-wrapper > .icon, .element-wrapper > input {border-color:transparent!important;}');const provider=root.querySelector('calcite-dropdown.dropdown');const field=input.shadowRoot.querySelector('input');const icon=input.shadowRoot.querySelector('.element-wrapper > .icon');const edges=e=>{const s=getComputedStyle(e);return [s.borderTopColor,s.borderRightColor,s.borderBottomColor,s.borderLeftColor];};return {providerDisplay:getComputedStyle(provider).display,inputBorderColors:edges(field),iconBorderColors:edges(icon),searchShadow:getComputedStyle(search).boxShadow,searchBorderRadius:getComputedStyle(search).borderRadius,inputDisabled:field.disabled};}